// The production DSN waits 5s. A queue of writers stalled under host
// contention outlasts that, and modernc.org/sqlite does not always apply
// busy_timeout to BEGIN IMMEDIATE. Helpers wait longer and retry only
// lock contention; any other Upsert error stays a store defect.
const (
	hardenWriterBusyTimeoutMS = 30000
	hardenWriterBusyBudget    = 2 * time.Minute
)

func runHardenWriterHelper() {
	dbPath := os.Getenv("PP_STORE_HARDEN_DB")
	if dbPath == "" {
		fmt.Fprintln(os.Stderr, "PP_STORE_HARDEN_DB is required")
		os.Exit(2)
	}
	id := os.Getenv("PP_STORE_HARDEN_ID")
	rounds := 15
	if v := os.Getenv("PP_STORE_HARDEN_ROUNDS"); v != "" {
		if n, scanErr := fmt.Sscanf(v, "%d", &rounds); n != 1 || scanErr != nil || rounds <= 0 {
			rounds = 15
		}
	}
	s, err := Open(dbPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "open: %v\n", err)
		os.Exit(3)
	}
	defer s.Close()
	if err := raiseHardenWriterBusyTimeout(s.DB()); err != nil {
		fmt.Fprintf(os.Stderr, "busy_timeout: %v\n", err)
		os.Exit(3)
	}
	deadline := time.Now().Add(hardenWriterBusyBudget)
	for i := 0; i < rounds; i++ {
		rowID := fmt.Sprintf("w%s-%d", id, i)
		if err := upsertConcurrentUntilSettled(s, rowID, deadline); err != nil {
			fmt.Fprintf(os.Stderr, "upsert %s: %v\n", rowID, err)
			os.Exit(4)
		}
	}
}

// Open pools two connections. busy_timeout is per connection, so the helper
// pins the pool to one before raising it. Otherwise Upsert can still use a
// connection that kept the 5s DSN timeout.
func raiseHardenWriterBusyTimeout(db *sql.DB) error {
	db.SetMaxOpenConns(1)
	if _, err := db.Exec(fmt.Sprintf("PRAGMA busy_timeout = %d", hardenWriterBusyTimeoutMS)); err != nil {
		return err
	}
	var got int
	if err := db.QueryRow(`PRAGMA busy_timeout`).Scan(&got); err != nil {
		return err
	}
	if got != hardenWriterBusyTimeoutMS {
		return fmt.Errorf("busy_timeout = %d, want %d", got, hardenWriterBusyTimeoutMS)
	}
	return nil
}

func upsertConcurrentUntilSettled(s *Store, rowID string, deadline time.Time) error {
	payload := json.RawMessage(fmt.Sprintf(`{"id":%q}`, rowID))
	backoff := 5 * time.Millisecond
	for {
		err := s.Upsert("concurrent", rowID, payload)
		if !sqliteBusyOrLocked(err) {
			return err
		}
		if !time.Now().Before(deadline) {
			return err
		}
		time.Sleep(backoff)
		backoff = min(backoff*2, 100*time.Millisecond)
	}
}

func sqliteBusyOrLocked(err error) bool {
	if err == nil {
		return false
	}
	msg := strings.ToLower(err.Error())
	return strings.Contains(msg, "busy") || strings.Contains(msg, "locked")
}

func TestSQLiteBusyOrLockedClassifiesContention(t *testing.T) {
	for _, msg := range []string{
		"database is locked (5) (SQLITE_BUSY)",
		"database table is locked (SQLITE_LOCKED)",
		"SQLITE_BUSY",
		"busy",
	} {
		if !sqliteBusyOrLocked(errors.New(msg)) {
			t.Fatalf("sqliteBusyOrLocked(%q) = false, want true", msg)
		}
	}
	if sqliteBusyOrLocked(nil) {
		t.Fatal("nil error must not retry")
	}
	if sqliteBusyOrLocked(errors.New("no such table: resources")) {
		t.Fatal("schema errors must not retry")
	}
}

